  protected override void Initialize() {
    this.InitSpecialTokens((int)Tokens.error, (int)Tokens.EOF);
    this.InitStates(states);
    this.InitRules(rules);
    this.InitNonTerminals(nonTerms);
  }

  protected override void DoAction(int action)
  {
    switch (action)
    {
      case 2: // program -> stmt_list, optional_semicolon, END_OF_FILE
{
			if (!is_unit_to_be_parsed) {
				var stl = ValueStack[ValueStack.Depth-3].stn as statement_list;
				stl.left_logical_bracket = new token_info("");
				stl.right_logical_bracket = new token_info("");
				var bl = new block(new declarations(), stl, CurrentLocationSpan);
				root = CurrentSemanticValue.stn = NewProgramModule(null, null, new uses_list(), bl, ValueStack[ValueStack.Depth-2].ob, CurrentLocationSpan);
				root.source_context = bl.source_context;
			}
			else {
				var interface_part = new interface_node(new declarations(), new uses_list(), null, null);
				var initialization_part = new initfinal_part(null, ValueStack[ValueStack.Depth-3].stn as statement_list, null, null, null, CurrentLocationSpan);

				root = CurrentSemanticValue.stn = new unit_module(
					new unit_name(new ident(Path.GetFileNameWithoutExtension(parserTools.currentFileName)),
					UnitHeaderKeyword.Unit, CurrentLocationSpan), interface_part, null,
					initialization_part.initialization_sect,
					initialization_part.finalization_sect, null, CurrentLocationSpan);
			}

		}
        break;
      case 3: // task_definition -> TASK, task_id, COLON, block
{
	CurrentSemanticValue.stn = new task_stmt(
		ValueStack[ValueStack.Depth-3].id as ident, 
		ValueStack[ValueStack.Depth-1].stn as statement_list,
		CurrentLocationSpan
	);
    }
        break;
      case 4: // input_section -> INPUT, COLON, block
{
          CurrentSemanticValue.stn = new input_section(ValueStack[ValueStack.Depth-1].stn as statement_list);
      }
        break;
      case 5: // input_section -> /* empty */
{
          CurrentSemanticValue.stn = null;
      }
        break;
      case 6: // check_section -> CHECK, COLON, block
{ 
                CurrentSemanticValue.stn = new check_section(ValueStack[ValueStack.Depth-1].stn as statement_list);
      }
        break;
      case 7: // check_section -> /* empty */
{ CurrentSemanticValue.stn = null; }
        break;
      case 8: // tests_section -> TESTS, COLON, block
{ 
                CurrentSemanticValue.stn = new tests_section(ValueStack[ValueStack.Depth-1].stn as statement_list);
      }
        break;
      case 9: // tests_section -> /* empty */
{ CurrentSemanticValue.stn = null; }
        break;
      case 10: // output_section -> OUTPUT, COLON, block
{ 
                CurrentSemanticValue.stn = new output_section(ValueStack[ValueStack.Depth-1].stn as statement_list);
      }
        break;
      case 11: // output_section -> /* empty */
{ CurrentSemanticValue.stn = null; }
        break;
      case 12: // stmt_list -> stmt
{
			CurrentSemanticValue.stn = new statement_list(ValueStack[ValueStack.Depth-1].stn as statement, CurrentLocationSpan);
		}
        break;
      case 13: // stmt_list -> stmt_list, end_of_line, stmt
{
			CurrentSemanticValue.stn = (ValueStack[ValueStack.Depth-3].stn as statement_list).Add(ValueStack[ValueStack.Depth-1].stn as statement, CurrentLocationSpan);
		}
        break;
      case 14: // stmt -> assign_stmt
{ 
			CurrentSemanticValue.stn = ValueStack[ValueStack.Depth-1].stn; 
		}
        break;
      case 15: // stmt -> var_stmt
{ 
			CurrentSemanticValue.stn = ValueStack[ValueStack.Depth-1].stn; 
