        break;
      case 20: // stmt -> input_section
{ CurrentSemanticValue.stn = ValueStack[ValueStack.Depth-1].stn; }
        break;
      case 21: // stmt -> check_section
{ CurrentSemanticValue.stn = ValueStack[ValueStack.Depth-1].stn; }
